import{_ as r,C as s,o as a,c as n,j as t,a as i,E as d,a2 as h}from"./chunks/framework.sc8Z_ZE3.js";const w=JSON.parse('{"title":"Settings per repository","description":"","frontmatter":{},"headers":[],"relativePath":"review-bot/settings.md","filePath":"review-bot/settings.md"}'),c={name:"review-bot/settings.md"};function l(u,e,p,f,g,b){const o=s("Badge");return a(),n("div",null,[e[0]||(e[0]=t("h1",{id:"settings-per-repository",tabindex:"-1"},[i("Settings per repository "),t("a",{class:"header-anchor",href:"#settings-per-repository","aria-label":'Permalink to "Settings per repository"'},"​")],-1)),d(o,{type:"built",text:"Built"}),e[1]||(e[1]=h(' Each repository has its own review bot settings. Workspace admins and owners change them; members can read them.<h2 id="in-the-settings-page" tabindex="-1">In the settings page <a class="header-anchor" href="#in-the-settings-page" aria-label="Permalink to &quot;In the settings page&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Values</th><th>Default</th></tr></thead><tbody><tr><td><strong>Review pull requests</strong></td><td>Off · On every push (webhook) · Hourly sync · Webhook and hourly sync</td><td>Off</td></tr><tr><td><strong>Status on the pull request</strong></td><td>Inform · Required check</td><td>Inform</td></tr><tr><td><strong>Review drafts</strong></td><td>on or off</td><td>off</td></tr><tr><td><strong>Protected branches</strong></td><td>branch names</td><td>none</td></tr><tr><td><strong>Fix runs</strong></td><td>on or off</td><td>off</td></tr><tr><td><strong>Size brake</strong></td><td>Lines and Files, whole numbers from 1 to 100,000</td><td>800 lines, 25 files</td></tr><tr><td><strong>Hotspot paths</strong></td><td>up to 50 globs</td><td>none</td></tr></tbody></table><p>Above the repository cards, <strong>Review on my seat</strong> is each person&#39;s own choice; see <a href="#review-on-my-seat">below</a>.</p><h3 id="status-on-the-pull-request" tabindex="-1">Status on the pull request <a class="header-anchor" href="#status-on-the-pull-request" aria-label="Permalink to &quot;Status on the pull request&quot;">​</a></h3><p>The bot sets a commit status: <code>octryx/review</code> on GitHub, <code>octryx-review</code> on GitLab and Bitbucket. The names differ on purpose: GitHub uses the usual <code>context/name</code> form, while Bitbucket carries the key in a URL path where <code>/</code> is not possible, and GitLab follows Bitbucket. It shows <strong>pending</strong> while the review runs, then passes or fails.</p><ul><li><strong>Inform</strong> (recommended): the status passes and counts every finding, lows included, for example &quot;Informational: 2 finding(s) to look at: 1 high · 1 medium · 1 low&quot;, or &quot;No blocking findings · 1 low&quot;. Nobody is blocked.</li><li><strong>Required check</strong>: the status fails when the review finds a blocking problem, which means a high or medium finding, or when the verdict is &quot;changes requested&quot;. It blocks a merge only where the repository&#39;s branch protection (or GitLab&#39;s &quot;Pipelines must succeed&quot;) requires the status.</li></ul><p>A failed CI check, or a caller outside the diff that the change breaks, is added as a high finding. Under <strong>Required check</strong> that fails the status; under <strong>Inform</strong> it is reported and the status stays green.</p><p>When someone ignores the last blocking finding with <code>@octryx ignore</code>, a failed status turns green: &quot;No blocking findings (1 ignored)&quot;.</p><p>A committed secret always fails the status, under <strong>Inform</strong> too: &quot;1 committed secret(s): remove and rotate&quot;. The summary lists it as blocking, and the secret&#39;s value is never quoted. See <a href="/docs/review-bot/#scanners">Scanners</a>.</p><h3 id="review-drafts" tabindex="-1">Review drafts <a class="header-anchor" href="#review-drafts" aria-label="Permalink to &quot;Review drafts&quot;">​</a></h3><p>Off: a draft pull request is reviewed once it is marked ready for review. On: drafts are reviewed too.</p><h3 id="protected-branches" tabindex="-1">Protected branches <a class="header-anchor" href="#protected-branches" aria-label="Permalink to &quot;Protected branches&quot;">​</a></h3><p>Branch names a <a href="/docs/review-bot/commands#fix">fix run</a> never pushes to, besides the target branch.</p><h3 id="fix-runs" tabindex="-1">Fix runs <a class="header-anchor" href="#fix-runs" aria-label="Permalink to &quot;Fix runs&quot;">​</a></h3><p>On: <code>@octryx fix</code> and <code>@octryx write tests</code> in a pull request comment may push onto that pull request&#39;s branch, never a protected branch, never forced. Off: the bot only reviews. A fix run also needs the <strong>PR fix</strong> workflow, which a platform admin switches on in <strong>Agents › Workflows</strong>. See <a href="/docs/review-bot/commands#fix">Commands</a>.</p><h3 id="size-brake" tabindex="-1">Size brake <a class="header-anchor" href="#size-brake" aria-label="Permalink to &quot;Size brake&quot;">​</a></h3><p>Above either limit, the review adds &quot;Large pull request&quot; with a suggested split into stacked pull requests. It never blocks and never changes the status.</p><h3 id="hotspot-paths" tabindex="-1">Hotspot paths <a class="header-anchor" href="#hotspot-paths" aria-label="Permalink to &quot;Hotspot paths&quot;">​</a></h3><p>Files matching these globs, for example <code>src/auth/**</code>, are read with extra care, besides the built-in sensitive areas. They are listed under <strong>Look closely here</strong> in the summary.</p><h2 id="review-on-my-seat" tabindex="-1">Review on my seat <a class="header-anchor" href="#review-on-my-seat" aria-label="Permalink to &quot;Review on my seat&quot;">​</a></h2><p>When on, the bot may offer this Workspace&#39;s pull request reviews to your device and your own Claude subscription. The first free seat takes a review; without one it runs on the company route. It is your choice only: on by default for admins and owners, off for everyone else. See <a href="/docs/review-bot/#where-the-review-runs">Where the review runs</a>.</p><h2 id="through-the-api" tabindex="-1">Through the API <a class="header-anchor" href="#through-the-api" aria-label="Permalink to &quot;Through the API&quot;">​</a></h2><p>Every setting can also be set with <code>PUT /api/v1/workspaces/{workspace}/repositories/{repository}/pr-review-bot</code> (<code>trigger</code>, <code>status_policy</code>, <code>review_drafts</code>, <code>protected_branches</code>, <code>fix_runs</code>, <code>size_limit_lines</code>, <code>size_limit_files</code>, <code>hotspot_paths</code>). The call changes only the fields it sends. Every change is recorded in the audit log.</p>',24))])}const v=r(c,[["render",l]]);export{w as __pageData,v as default};
